}"},{"path":"Services/UserService.cs","content":"using MyFirstApi.Models;

namespace MyFirstApi.Services;

public class UserService : IUserService
{
    private readonly List<User> _users =
    [
        new User(1, "Arman", "arman@example.com"),
        new User(2, "Sara", "sara@example.com")
    ];

    public IReadOnlyList<User> GetAll() => _users;

    public User? GetById(int id) =>
        _users.FirstOrDefault(user => user.Id == id);
